<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api,bootstrap,notify} from '../composables/api'
import {date} from '../composables/investigation'
import {useCollaborationAction} from '../composables/collaboration'
import type {GitHubLink,GitHubPreview,IntegrationConnection,IntegrationConfiguration} from '../types'
const props=defineProps<{issue:string}>(),links=ref<GitHubLink[]>([]),connections=ref<IntegrationConnection[]>([]),error=ref(''),loading=ref(true),saving=ref(false),mode=ref<'create'|'link'|'recreate'|null>(null),connection=ref(''),title=ref(''),labels=ref<string[]>([]),number=ref(''),preview=ref<GitHubPreview|null>(null),previewKey=ref(''),confirmedNone=ref(false),inspection=ref<{matches:{number:number;url:string}[];message:string}|null>(null),perform=useCollaborationAction()
const eligibleConnections=computed(()=>mode.value==='create'?connections.value.filter(c=>!links.value.some(l=>l.connection===c.id&&!['unlinked','unavailable'].includes(l.state))):connections.value),canCreate=computed(()=>connections.value.some(c=>!links.value.some(l=>l.connection===c.id&&!['unlinked','unavailable'].includes(l.state))))
const canOperate=computed(()=>bootstrap.value?.capabilities.operate),chosen=computed(()=>connections.value.find(c=>c.id===connection.value)),association=computed(()=>links.value.find(l=>l.connection===connection.value)),dirty=computed(()=>mode.value!==null&&(!!title.value||!!number.value||!!preview.value))
function leave(){return !dirty.value||window.confirm('Discard this unconfirmed GitHub export/link draft?')}
onBeforeRouteLeave(leave);onBeforeRouteUpdate((to,from)=>to.params.issue===from.params.issue&&to.query.tab===from.query.tab||leave())
watch([title,labels,connection],()=>{preview.value=null},{deep:true})
async function load(){loading.value=true;try{const [l,c]=await Promise.all([api<GitHubLink[]>('/issues/'+props.issue+'/github'),api<IntegrationConfiguration>('/integrations')]);links.value=l;connections.value=c.connections.filter(c=>c.provider==='github'&&c.enabled&&!c.disconnected);error.value=''}catch(e){error.value=e instanceof Error?e.message:'GitHub links unavailable.'}finally{loading.value=false}}
const unload=(e:BeforeUnloadEvent)=>{if(dirty.value){e.preventDefault();e.returnValue=''}};onMounted(()=>{load();window.addEventListener('beforeunload',unload)});onUnmounted(()=>window.removeEventListener('beforeunload',unload));watch(()=>props.issue,()=>{mode.value=null;preview.value=null;load()})
function open(kind:'create'|'link'|'recreate',link?:GitHubLink){if(!leave())return;mode.value=kind;connection.value=link?.connection??(kind==='create'?connections.value.find(c=>!links.value.some(l=>l.connection===c.id&&!['unlinked','unavailable'].includes(l.state))):connections.value[0])?.id??'';title.value='';number.value='';labels.value=[];preview.value=null;previewKey.value=crypto.randomUUID();confirmedNone.value=false;inspection.value=null}
async function review(){saving.value=true;try{preview.value=await api('/issues/'+props.issue+'/github/preview','POST',{connection:connection.value,preview_key:previewKey.value,...(title.value?{title:title.value}:{}),labels:labels.value})}catch(e){error.value=e instanceof Error?e.message:'Preview failed.'}finally{saving.value=false}}
async function create(){if(!preview.value)return;saving.value=true;try{await perform('/issues/'+props.issue+'/github/'+mode.value,'POST',{connection:connection.value,preview_key:previewKey.value,...(title.value?{title:title.value}:{}),labels:labels.value,preview_digest:preview.value.digest,link_version:preview.value.link_version,...(mode.value==='recreate'?{confirm_no_ticket:confirmedNone.value}:{})});mode.value=null;preview.value=null;notify('GitHub creation reserved. Follow the durable delivery outcome.');await load()}catch(e){error.value=e instanceof Error?e.message:'Creation could not be queued.'}finally{saving.value=false}}
async function link(){saving.value=true;try{await perform('/issues/'+props.issue+'/github/link','POST',{connection:connection.value,version:association.value?.version??0,number:number.value});mode.value=null;await load()}catch(e){error.value=e instanceof Error?e.message:'Link could not be validated.'}finally{saving.value=false}}
async function action(l:GitHubLink,kind:string){if(kind==='unlink'&&!window.confirm('Remove only this local association? The GitHub issue will stay open or closed as it is.'))return;saving.value=true;try{const result=await perform<{matches:{number:number;url:string}[];message:string}>('/issues/'+props.issue+'/github/'+kind,'POST',{link:l.id,version:l.version});if(kind==='inspect')inspection.value=result;await load()}catch(e){error.value=e instanceof Error?e.message:'Repository operation unavailable.'}finally{saving.value=false}}
</script>
<template><section class="github-panel"><p v-if="bootstrap?.features.controlled_integrations" class="notice neutral">Controlled preview · no external requests are sent.</p><div class="section-heading"><h3>Linked GitHub issues</h3><button class="button" :disabled="loading||saving" @click="load">Refresh local status</button></div><p class="help">One association per error and repository. Local Resolve/Ignore actions never close or reopen external tickets.</p><div v-if="error" class="notice danger" role="alert">{{error}}<button class="button" @click="load">Reload links</button></div><p v-if="loading" role="status">Loading GitHub associations…</p><p v-if="!loading&&!links.length">No GitHub issue linked yet.</p><article v-for="l in links" :key="l.id" class="github-association"><div class="section-heading"><h4>{{l.repository}}</h4><span class="status-badge" :class="l.state==='needs_review'?'status-failed':''">{{l.state.replaceAll('_',' ')}}</span></div><a v-if="l.url&&l.state!=='unlinked'" :href="l.url" target="_blank" rel="noopener noreferrer" class="text-link">Open GitHub issue #{{l.number}}</a><p v-if="l.remote_state" class="help">Last known state: {{l.remote_state}}. Latest check: {{date(l.checked_at)}}{{l.state==='unavailable'?' · unavailable; the state was last observed before this check.':'.'}} Unavailable does not mean closed.</p><p v-if="l.state==='creating'||l.state==='reserved'" class="help">A durable creation is reserved. Repeated clicks do not queue independent tickets.</p><div v-if="l.state==='needs_review'" class="notice warning"><div><strong>Creation acceptance is unknown</strong><p>Check the repository or link an existing issue. A missing search result is not proof that no ticket was created. Another creation requires your explicit confirmation.</p></div></div><div v-if="canOperate" class="inline-actions"><button v-if="['linked','unavailable'].includes(l.state)&&l.number" class="button" :disabled="saving" @click="action(l,'refresh')">Refresh GitHub state</button><button v-if="l.state==='needs_review'" class="button" :disabled="saving" @click="action(l,'inspect')">Check repository</button><button v-if="['needs_review','unlinked','unavailable'].includes(l.state)" class="button" :disabled="saving" @click="open('link',l)">Link existing issue</button><button v-if="l.state==='needs_review'" class="button" :disabled="saving" @click="open('recreate',l)">Review a new attempt</button><button v-if="['linked','unavailable'].includes(l.state)" class="text-link danger-link" :disabled="saving" @click="action(l,'unlink')">Unlink locally</button></div><RouterLink v-if="l.delivery" :to="'/alerts/history/'+l.delivery" class="text-link">Inspect creation delivery</RouterLink></article>
<section v-if="inspection" class="notice neutral"><div><p>{{inspection.message}}</p><ul><li v-for="m in inspection.matches" :key="m.number"><a :href="m.url" rel="noopener noreferrer" target="_blank">Candidate issue #{{m.number}}</a></li></ul><p v-if="!inspection.matches.length">No matching ticket found on the inspected page. The reservation remains protected.</p></div></section>
<div v-if="canOperate&&connections.length" class="inline-actions spacing"><button class="button primary" :disabled="saving||!canCreate" @click="open('create')">Create GitHub issue</button><button class="button" :disabled="saving" @click="open('link')">Link existing issue</button></div><p v-if="!connections.length" class="help">An administrator must enable a repository connection before creating or linking tickets. <RouterLink to="/integrations" class="text-link">Review integrations</RouterLink></p>
<form v-if="mode" class="github-export-form" @submit.prevent="mode==='link'?link():review()"><h4>{{mode==='link'?'Link an existing issue':mode==='recreate'?'Review a new creation attempt':'Review GitHub export'}}</h4><label class="field">Repository<select v-model="connection" required><option v-for="c in eligibleConnections" :key="c.id" :value="c.id">{{c.display}}</option></select></label><label v-if="mode==='link'" class="field">Issue number or canonical URL<input v-model="number" required placeholder="42 or https://github.com/owner/repo/issues/42"></label><template v-else><label class="field">Title (optional override)<input v-model="title" maxlength="256" placeholder="Use sanitized exception summary"></label><fieldset v-if="chosen?.options.known_labels?.length"><legend>Existing labels</legend><label v-for="name in chosen.options.known_labels" :key="name" class="checkbox-row"><input v-model="labels" type="checkbox" :value="name">{{name}}</label></fieldset><label v-if="mode==='recreate'" class="checkbox-row"><input v-model="confirmedNone" type="checkbox" required>I checked the repository and confirm no ticket exists. A new attempt may still create a duplicate.</label><p class="help">The exported body contains sanitized summary metadata and an investigation link. Includes permitted execution details and a bounded application stack trace. Request data, SQL, user identities and notes are excluded.</p></template><div class="inline-actions"><button class="button" :disabled="saving||!connection||(mode==='recreate'&&!confirmedNone)">{{mode==='link'?'Validate and link':'Preview exact export'}}</button><button type="button" class="button" :disabled="saving" @click="leave()&&(mode=null)">Cancel draft</button></div><section v-if="preview&&mode!=='link'" class="github-exact-preview"><h4>{{preview.repository}} · {{preview.title}}</h4><pre>{{preview.body}}</pre><p class="help">Confirm these exact sanitized bytes. Later incompatible privacy changes cancel this export.</p><button type="button" class="button primary" :disabled="saving||(mode==='recreate'&&!confirmedNone)" @click="create">Confirm {{mode==='recreate'?'new creation attempt':'GitHub issue creation'}}</button></section></form></section></template>
